  'Economic / Political Anthropology',
  'This course studies how people organize material life and political authority across diverse societies and global systems. Students examine exchange, labor, money, debt, property, development, bureaucracy, law, sovereignty, inequality, violence, neoliberalism, extraction, and social movements through ethnographic and theoretical lenses. The syllabus centers on power, value, obligation, and evidence through a granular anthropology outline.',
  $epanjson${"slug": "economic-political-anthropology", "title": "Economic / Political Anthropology", "description": "This course studies how people organize material life and political authority across diverse societies and global systems. Students examine exchange, labor, money, debt, property, development, bureaucracy, law, sovereignty, inequality, violence, neoliberalism, extraction, and social movements through ethnographic and theoretical lenses. The syllabus centers on power, value, obligation, and evidence through a granular anthropology outline.", "topics": [{"id": "01e6557d-633d-4168-8d86-e2a16a6972fc", "type": "topic", "title": "Economic and Political Anthropology as a Field", "description": "Introduces the course's central problem: how humans organize livelihood, value, exchange, authority, coercion, obligation, and inequality in culturally specific but globally connected ways.", "children": [{"id": "d0955a08-1a60-4e5d-b3bc-12ccf6fa5bf1", "type": "subtopic", "title": "Core questions and analytic scale", "children": [{"id": "04a5850a-7c1c-42c6-b408-47f230d1813b", "type": "concept", "title": "Livelihood"}, {"id": "aca67dba-987b-4d4f-9266-7ff1928884de", "type": "concept", "title": "Value"}, {"id": "7b75b96f-7d28-4138-9f72-3b461c0e300b", "type": "concept", "title": "Authority"}, {"id": "df3fee3d-5851-4fcb-b6a6-765832468c56", "type": "concept", "title": "Power"}, {"id": "f7618e99-c845-4cf2-bf5a-a6d7d47ee56c", "type": "concept", "title": "Scale"}, {"id": "d0b0e5f2-6736-4635-a815-fcb103dcb3f2", "type": "concept", "title": "Embeddedness"}], "description": "Students learn to ask how household life, markets, states, empires, and global systems connect rather than treating economy and politics as separate boxes."}, {"id": "f698dda9-f754-4f0c-975f-2f503c756601", "type": "subtopic", "title": "Economy and politics as cultural systems", "children": [{"id": "c45f0ec0-7111-47c7-9243-6207622cf77a", "type": "concept", "title": "Moral order"}, {"id": "611c7256-3a04-417d-a019-cbec91efc180", "type": "concept", "title": "Institution"}, {"id": "0fcbed94-fa2c-458e-82b0-a985bad54553", "type": "concept", "title": "Practice"}, {"id": "2dc2f3eb-5426-4267-bb6f-bef6d9d66143", "type": "concept", "title": "Personhood"}, {"id": "27cb2c6d-fbdd-434d-858f-88e3b62656ff", "type": "concept", "title": "Obligation"}, {"id": "8fb8e659-2cfc-42ab-bbcb-34a7f9a7b2e5", "type": "concept", "title": "Legitimacy"}], "description": "This subtopic shows why anthropologists study money, markets, states, and law as moral and symbolic orders as well as institutions."}, {"id": "b1fb048c-c5ec-4595-8528-57216d06f101", "type": "subtopic", "title": "Ethnography of power and exchange", "children": [{"id": "3c0af639-7da1-4d11-b00d-c9b2c8850c79", "type": "concept", "title": "Participant observation"}, {"id": "f18e36d5-810e-43f4-830b-abe2d7304a08", "type": "concept", "title": "Fieldsite"}, {"id": "27435362-37e9-442b-a10b-48bcec6af5ec", "type": "concept", "title": "Thick description"}, {"id": "5bbf8fb4-d751-4a40-99bd-96869d731b53", "type": "concept", "title": "Everyday politics"}, {"id": "1646effa-f00a-473b-a2cb-cf636fca7933", "type": "concept", "title": "Relational analysis"}, {"id": "b2b0a0ff-49d4-4d91-a825-360f6409673b", "type": "concept", "title": "Historical context"}], "description": "Students see how fieldwork reveals informal, everyday, and contested dimensions of economic and political life."}]}, {"id": "15dd8c0f-4929-4ef4-bbe0-56b089875c8b", "type": "topic", "title": "Gift, Commodity, and Exchange Theory", "description": "Builds from classic exchange theory to modern debates about reciprocity, obligation, commodity circulation, and social relationships.", "children": [{"id": "7463419f-a1bb-4b70-bbf1-bab5f94a4a20", "type": "subtopic", "title": "The gift and reciprocity", "children": [{"id": "f9c6d52c-4c69-4280-9734-bcce4bd86ad6", "type": "concept", "title": "Mauss"}, {"id": "537b109c-dce0-4291-95c5-a2bf648bc763", "type": "concept", "title": "Reciprocity"}, {"id": "ae1c189f-9ab2-41ac-961e-45d49e438792", "type": "concept", "title": "Obligation to give"}, {"id": "759c4ba3-5d3b-4b47-8b49-873dab5b6ab2", "type": "concept", "title": "Obligation to receive"}, {"id": "11164b07-429c-4b5f-9de3-9fc0c5aa2858", "type": "concept", "title": "Obligation to return"}, {"id": "ab51bac6-554d-4504-8116-93cf0979e4cf", "type": "concept", "title": "Prestige"}], "description": "The point is to understand exchange as relationship-making, not merely transfer of goods."}, {"id": "24aa4a28-ab11-447a-a739-76b586f4b9f9", "type": "subtopic", "title": "Commodity exchange and alienability", "children": [{"id": "c9aac3a4-1964-4b82-82a3-62d29158b7ca", "type": "concept", "title": "Commodity"}, {"id": "fd3646b4-e57d-4384-9485-ea47f0fb8ebc", "type": "concept", "title": "Alienability"}, {"id": "c8fe5c38-e56e-48f9-8670-926826592897", "type": "concept", "title": "Use value"}, {"id": "b0bdc5e6-fc66-4884-b235-db64cf331738", "type": "concept", "title": "Exchange value"}, {"id": "21c2ca89-bac2-443d-bcec-d3c81def4c39", "type": "concept", "title": "Commodification"}, {"id": "c4ab8394-a4d9-4083-b028-aaa4ef81ce4d", "type": "concept", "title": "Singularization"}], "description": "Students compare gifts and commodities by asking what is separable from persons, places, histories, and obligations."}, {"id": "964a6f67-d2cf-4c6d-b45e-09949fdec36b", "type": "subtopic", "title": "Exchange systems and social rank", "children": [{"id": "0a3c7e09-d552-40d9-81f2-fb36d19272fa", "type": "concept", "title": "Kula"}, {"id": "9a4363ad-3107-4d78-a804-1876d33431e0", "type": "concept", "title": "Potlatch"}, {"id": "362220ca-d3c7-4455-9983-0083d1b22561", "type": "concept", "title": "Bridewealth"}, {"id": "996b98e3-4a50-470e-852b-24c0e5a30013", "type": "concept", "title": "Dowry"}, {"id": "5f2beb74-315b-4ae9-bf41-e6af7e97146b", "type": "concept", "title": "Redistribution"}, {"id": "cfa3dac5-acaf-4aac-bc3b-c130b22f73ec", "type": "concept", "title": "Rank"}], "description": "This subtopic links exchange to hierarchy, alliance, rivalry, ritual, and redistribution."}]}, {"id": "8d35c481-6e97-47e2-99b4-2045bae3d5f3", "type": "topic", "title": "Labor, Value, and Household Economies", "description": "Examines how work, production, care, subsistence, kinship, and households organize economic life beyond formal wage labor.", "children": [{"id": "d25a9022-7da1-4ffc-9b57-01a58b8f60ea", "type": "subtopic", "title": "Labor and value", "children": [{"id": "93e8dd9d-9d7d-4bb5-af44-1559802ec7ec", "type": "concept", "title": "Labor power"}, {"id": "49d8292b-abff-4b97-971c-957373e66425", "type": "concept", "title": "Surplus"}, {"id": "d673ccc7-bb39-4e28-bae4-c056676d3e5e", "type": "concept", "title": "Value regimes"}, {"id": "d78b63f7-f65a-4b7f-929d-7ab7c3166c19", "type": "concept", "title": "Use value"}, {"id": "16054402-9b52-485e-9280-d0fbd81eca34", "type": "concept", "title": "Socially necessary labor"}, {"id": "aa354af8-b4f9-47dd-9e7e-e6d924aa21b3", "type": "concept", "title": "Exploitation"}], "description": "Students learn how anthropologists analyze value as produced through work, social relations, scarcity, morality, and recognition."}, {"id": "5f9275ad-e6e9-4dee-9861-0eeeaa6428d6", "type": "subtopic", "title": "Household and kin-based economies", "children": [{"id": "569b8e1d-063b-4edb-820f-24f8b121361d", "type": "concept", "title": "Domestic mode of production"}, {"id": "698ed505-1b02-464a-a455-a091b03befe3", "type": "concept", "title": "Household strategy"}, {"id": "065dc4e8-07ad-463b-a3b4-4886cdd049a6", "type": "concept", "title": "Kin obligations"}, {"id": "fb33e5b2-2bc6-439e-a4da-6e0c79e7266a", "type": "concept", "title": "Gendered labor"}, {"id": "fe5757d6-aa97-4d90-b413-e5597d155a23", "type": "concept", "title": "Subsistence"}, {"id": "747ac863-51e3-4ac2-82f5-bd841105cfdb", "type": "concept", "title": "Informal economy"}], "description": "This subtopic explains how families, kin groups, and households allocate work, risk, food, income, and care."}, {"id": "281b6b2d-2176-4815-b782-2cbbd97dcb8d", "type": "subtopic", "title": "Care, reproduction, and hidden work", "children": [{"id": "fcc9f57e-6028-49ff-b1e0-7dd68c63a037", "type": "concept", "title": "Social reproduction"}, {"id": "90b99120-7353-40ff-85c7-49741664ec21", "type": "concept", "title": "Care work"}, {"id": "81274c4c-30c1-4cfd-9d43-3dbea79946b1", "type": "concept", "title": "Emotional labor"}, {"id": "3f8e463d-fec9-49d1-a998-c82ceec33cf3", "type": "concept", "title": "Reproductive labor"}, {"id": "1acd741b-c959-424b-b7e1-45a949ab9c61", "type": "concept", "title": "Interdependence"}, {"id": "c8c21cd1-72bc-4b56-8681-3f6eef57cf81", "type": "concept", "title": "Time poverty"}], "description": "Students examine the economic importance of caregiving, social reproduction, emotional labor, and unpaid labor."}]}, {"id": "fff82dca-813e-4ea2-a4b1-7a3ccf33bd31", "type": "topic", "title": "Markets, Money, and Moral Economies", "description": "Explores markets and money as moral, political, and culturally organized systems rather than neutral mechanisms.", "children": [{"id": "ba0f3453-b5d1-4207-8d1a-c0bc0fd8acec", "type": "subtopic", "title": "Embedded markets", "children": [{"id": "c7b010ff-2ccd-4600-9956-be6ee9dfdf95", "type": "concept", "title": "Polanyi"}, {"id": "eb37de3a-fba4-421e-b559-21623eee5bff", "type": "concept", "title": "Embeddedness"}, {"id": "632bd5b5-e454-4194-9418-336376481a85", "type": "concept", "title": "Market society"}, {"id": "24b08a00-127e-446d-bf89-46f2500d9c4c", "type": "concept", "title": "Reciprocity"}, {"id": "3577a1f1-65e4-458a-add3-d481c1ecfbcd", "type": "concept", "title": "Redistribution"}, {"id": "1a7eb3e8-6903-423c-aa6d-94d3209b0864", "type": "concept", "title": "Householding"}], "description": "Students learn Polanyi's insight that markets are always embedded in legal, moral, kinship, religious, and state arrangements."}, {"id": "7df29784-57b8-4674-99e1-82d350768c35", "type": "subtopic", "title": "Money and multiple currencies", "children": [{"id": "dcafb517-47ef-4c66-85d0-65c07b2611b7", "type": "concept", "title": "Earmarking"}, {"id": "4df4a28d-e473-4926-a1b5-d4174e377d71", "type": "concept", "title": "Special monies"}, {"id": "29530b7f-1fa9-4d83-ae63-d929f04523af", "type": "concept", "title": "Debt"}, {"id": "edefd413-6298-4d8f-87b1-712e491a011a", "type": "concept", "title": "Credit"}, {"id": "a6bc8403-a149-445a-b2a3-4bcdbeb8ba76", "type": "concept", "title": "Moral accounting"}, {"id": "9fc07250-14ce-4f62-adb1-f8eacfa504c2", "type": "concept", "title": "Currency plurality"}], "description": "This subtopic shows that money carries social meanings and can be earmarked, ranked, restricted, or morally contested."}, {"id": "e96fc86c-4356-4c41-bf32-292a028f1500", "type": "subtopic", "title": "Moral economy", "children": [{"id": "da7bb663-74c5-4e96-86e0-51f3889f8c8a", "type": "concept", "title": "E. P. Thompson"}, {"id": "81045ae8-28ad-4db2-80f5-0c8068fd0073", "type": "concept", "title": "James Scott"}, {"id": "cc0f5d7b-a034-45eb-bf0d-e430fc02d933", "type": "concept", "title": "Subsistence ethic"}, {"id": "5289ff82-341b-4f5c-b1d9-9d7e8bc8d150", "type": "concept", "title": "Just price"}, {"id": "857dc1e5-6b11-43ac-b138-3c887018a842", "type": "concept", "title": "Food riots"}, {"id": "d4e3e386-b656-4115-b63d-e3c0a8088dd5", "type": "concept", "title": "Moral outrage"}], "description": "Students analyze how communities define fairness, survival rights, just prices, and legitimate extraction."}]}, {"id": "3295a12d-ba8c-4a5f-816e-ed34ac1cd4de", "type": "topic", "title": "Debt, Credit, Finance, and Obligation", "description": "Traces debt as an economic relation, moral language, legal instrument, and political technology.", "children": [{"id": "8932ae70-5333-40ce-b873-7e49b045b2db", "type": "subtopic", "title": "Debt as social relation", "children": [{"id": "9a173924-ade0-49a2-91e3-35d51e10c455", "type": "concept", "title": "Creditor"}, {"id": "e8cd7bd4-2892-42e2-a42c-88cdc940a769", "type": "concept", "title": "Debtor"}, {"id": "85717454-6f6a-4e99-b292-5770116f8df1", "type": "concept", "title": "Obligation"}, {"id": "d758fd12-8b88-44ff-84a8-2883463873ee", "type": "concept", "title": "Reciprocity"}, {"id": "125de71f-8a24-43b4-8605-51065c98639c", "type": "concept", "title": "Honor"}, {"id": "a92f3377-8e7c-484b-996c-fd6888d441bd", "type": "concept", "title": "Bondage"}], "description": "Students learn how debt creates hierarchy, dependency, trust, memory, and obligation."}, {"id": "d2628b5e-9a97-415b-9238-083d3458338f", "type": "subtopic", "title": "Credit, microfinance, and development", "children": [{"id": "f9fae323-1ab5-4729-bf77-353fec58809a", "type": "concept", "title": "Microcredit"}, {"id": "a9b37505-347d-49ef-a65f-018cee574ba5", "type": "concept", "title": "Financial inclusion"}, {"id": "4c59ad9c-7561-4387-9e5f-96e838126685", "type": "concept", "title": "Group lending"}, {"id": "ee09fb43-d5f5-4ffe-9edc-f51fe8cfb0c0", "type": "concept", "title": "Interest"}, {"id": "d163a18d-7e6e-4674-8bc2-760c63147e5e", "type": "concept", "title": "Default"}, {"id": "6a340b88-c478-4cad-ada2-2718e373c67a", "type": "concept", "title": "Debt discipline"}], "description": "This subtopic examines the promises and problems of lending as anti-poverty policy."}, {"id": "f3e3aefd-5ca1-40db-b1a4-ce6706811ecb", "type": "subtopic", "title": "Financialization", "children": [{"id": "7ed7598a-21da-4e44-8111-9259de28b2d6", "type": "concept", "title": "Financialization"}, {"id": "7fac74dc-dd1b-4df1-97f6-bb21a65c4c86", "type": "concept", "title": "Assetization"}, {"id": "9ae0cd8b-e0dd-4df9-bdd3-aa445c9fdd8b", "type": "concept", "title": "Risk"}, {"id": "f1a0f672-c352-48de-a4fd-ab2af4b2c1df", "type": "concept", "title": "Speculation"}, {"id": "bd13279b-b217-457b-93ee-eee68679aebb", "type": "concept", "title": "Derivatives"}, {"id": "279d4032-6ca2-44d5-9965-d3983917a7b2", "type": "concept", "title": "Household debt"}], "description": "Students analyze how finance expands into housing, education, health, land, climate, and everyday life."}]}, {"id": "9bf40dc4-25bc-43b2-a770-7dbd950ee1e5", "type": "topic", "title": "Property, Land, Commons, and Dispossession", "description": "Studies how rights to land, resources, housing, territory, knowledge, and commons are made, defended, stolen, and transformed.", "children": [{"id": "f0d930f0-c2ce-4089-8790-bedb715bc898", "type": "subtopic", "title": "Property regimes", "children": [{"id": "2e3d1fe3-f888-4772-b09f-70e92137d551", "type": "concept", "title": "Private property"}, {"id": "1311dd76-a571-4197-a726-44e9d3e64b60", "type": "concept", "title": "Common property"}, {"id": "4b3f1400-9024-45c9-af1d-c6721f67d378", "type": "concept", "title": "Customary tenure"}, {"id": "5f1ff765-9016-4fd3-b8bd-2b8f22ebdf98", "type": "concept", "title": "State land"}, {"id": "8fd758f9-bfa6-41af-bd8d-4547050ebbcb", "type": "concept", "title": "Usufruct"}, {"id": "0a660c73-6238-4e69-8458-63f8b79a2115", "type": "concept", "title": "Enclosure"}], "description": "Students compare private, collective, state, customary, and common property systems."}, {"id": "d7c40cb1-2741-4159-9437-8c3c9bb938fa", "type": "subtopic", "title": "Land, territory, and sovereignty", "children": [{"id": "d49f7b27-5e7e-45a9-8d96-355f38dc59b5", "type": "concept", "title": "Territory"}, {"id": "b58ae850-1872-42a8-87cf-2ae8dba32b1b", "type": "concept", "title": "Sovereignty"}, {"id": "1904ae6c-0dd7-4c03-a358-1350e5347a26", "type": "concept", "title": "Land claims"}, {"id": "ffb1ad24-e410-4897-96aa-46acfbb18881", "type": "concept", "title": "Cadastral mapping"}, {"id": "2164730d-b955-48e6-809c-256dad3bfcff", "type": "concept", "title": "Settler colonialism"}, {"id": "ff314e35-1e3d-4f2c-85d7-f4688c2efe01", "type": "concept", "title": "Jurisdiction"}], "description": "This subtopic links property to Indigenous rights, colonialism, mapping, borders, and jurisdiction."}, {"id": "4c9e2b9f-698a-445b-a5b1-1a489a8c7bbe", "type": "subtopic", "title": "Accumulation by dispossession", "children": [{"id": "e5d77c05-6383-4361-afa1-4bc9f762bc44", "type": "concept", "title": "Dispossession"}, {"id": "d7bf3951-a55e-4372-b1bf-48d75cff3e38", "type": "concept", "title": "Primitive accumulation"}, {"id": "3a243112-8b60-4aab-a4af-2766fc3c58a4", "type": "concept", "title": "Eviction"}, {"id": "70d2e768-535e-454f-9fd7-e762883726dc", "type": "concept", "title": "Privatization"}, {"id": "0d72168e-861c-4bb1-92c0-74f2e28c53fb", "type": "concept", "title": "Resource extraction"}, {"id": "1f897006-4a8a-421c-b1b1-2536985af8cf", "type": "concept", "title": "Gentrification"}], "description": "Students analyze how wealth is made through enclosure, eviction, privatization, extraction, and legal coercion."}]}, {"id": "a1937a2d-af46-4ac2-853a-bf6ed1fc770d", "type": "topic", "title": "Development, Aid, and Humanitarianism", "description": "Critically examines development as a field of expertise, intervention, measurement, aspiration, dependency, and political contestation.", "children": [{"id": "9f704c6e-ea05-470c-80bd-1864f277217b", "type": "subtopic", "title": "Development discourse", "children": [{"id": "2e5110ab-9141-4273-b54e-33e84dbaa6c4", "type": "concept", "title": "Modernization"}, {"id": "4990fe56-7564-4806-bbcc-8ba9f4678980", "type": "concept", "title": "Underdevelopment"}, {"id": "40b454a9-cc97-46bf-a854-4c34745e3b14", "type": "concept", "title": "Expertise"}, {"id": "428b7292-6bbd-4f55-be04-feea8db29827", "type": "concept", "title": "Project cycle"}, {"id": "0e3dbc04-ba56-4e9f-9b5b-4df8a9a110a4", "type": "concept", "title": "Indicators"}, {"id": "ef64c304-8e45-4bc2-a0c2-0d57ef4532c5", "type": "concept", "title": "Beneficiary"}], "description": "Students learn how development categories define problems and authorize interventions."}, {"id": "9c09729a-f1ad-482b-ae91-8448665be331", "type": "subtopic", "title": "Aid institutions and NGOs", "children": [{"id": "6f957616-032a-4b76-afac-a9aa1df16561", "type": "concept", "title": "NGO"}, {"id": "414d83d0-1b18-4cff-acc9-e2853913e980", "type": "concept", "title": "Donor"}, {"id": "ebd2ba30-ed5a-4c9a-a52a-ce4f6b594301", "type": "concept", "title": "Capacity building"}, {"id": "cd19fe2f-6a8d-4507-b596-1085cc0c25ba", "type": "concept", "title": "Accountability"}, {"id": "cd23c074-bc71-447a-a392-602e7be610c2", "type": "concept", "title": "Audit"}, {"id": "d410864b-cbed-4a04-bebb-3c91c051326f", "type": "concept", "title": "Participation"}], "description": "This subtopic studies the everyday bureaucracy, ethics, and unintended effects of aid work."}, {"id": "ef993523-f7e9-4a85-8dfd-152976aa59d2", "type": "subtopic", "title": "Humanitarian reason", "children": [{"id": "f73edcd8-06ae-4396-a63b-1ae45ac0a61b", "type": "concept", "title": "Humanitarianism"}, {"id": "ab342124-3a27-4add-ae10-d0942eb4d853", "type": "concept", "title": "Emergency"}, {"id": "d2af7fd0-a3ec-447a-98d3-1fd159ff01b6", "type": "concept", "title": "Triage"}, {"id": "7a3cf412-b148-4bc0-8115-dedb2d58f3b9", "type": "concept", "title": "Witnessing"}, {"id": "3d63cce6-fc6a-46cd-af92-3c9d12dcb49b", "type": "concept", "title": "Neutrality"}, {"id": "e27d089d-099c-44e8-af7e-0f94db934a55", "type": "concept", "title": "Victim subject"}], "description": "Students analyze emergency aid, suffering, compassion, triage, and the politics of saving lives."}]}, {"id": "057ddf03-0027-4de2-b137-e5ad4fdadf3a", "type": "topic", "title": "The State, Bureaucracy, and Everyday Governance", "description": "Explores the state not only as an institution but as a set of documents, encounters, infrastructures, categories, and performances.", "children": [{"id": "d07aabd8-12ab-45c7-98e9-93e37286729b", "type": "subtopic", "title": "Anthropology of the state", "children": [{"id": "2f4acceb-dc3c-4c9a-b065-9ecf55841053", "type": "concept", "title": "State effect"}, {"id": "84f8c6f4-8aeb-4595-a6df-3759834aa925", "type": "concept", "title": "Legibility"}, {"id": "5567ac92-a802-4a97-ad44-dde44f1390e1", "type": "concept", "title": "Governmentality"}, {"id": "3c3baa4f-ea9c-4937-b98b-f1b71f8bdbf0", "type": "concept", "title": "Sovereignty"}, {"id": "591b7276-bf14-4a0f-893f-b9ca229da9d2", "type": "concept", "title": "Territoriality"}, {"id": "da2dbfda-6b3b-4f88-bb4f-7ef527d7e302", "type": "concept", "title": "Rule"}], "description": "Students learn to study the state through everyday practices rather than only formal constitutions."}, {"id": "bc8b747b-c3ea-40d8-bd17-62c7ca84c0ea", "type": "subtopic", "title": "Bureaucratic practice", "children": [{"id": "f9c0aeb4-411d-4d2b-b266-40015b6cdd4a", "type": "concept", "title": "File"}, {"id": "223880c3-285e-4540-898a-d122b4e7fba6", "type": "concept", "title": "Permit"}, {"id": "bf5e91f6-af7f-4f9d-9e2d-4629bef77ec1", "type": "concept", "title": "Queue"}, {"id": "9f9be9b0-31da-4aeb-bd03-af3c6585969c", "type": "concept", "title": "Discretion"}, {"id": "88f7c07a-a00c-4ec6-bb62-b433c1ff7b95", "type": "concept", "title": "Documentation"}, {"id": "1ddcd63d-a794-42a2-b9c1-7000354cb712", "type": "concept", "title": "Street-level bureaucracy"}], "description": "This subtopic shows how paperwork, waiting, files, offices, and discretion shape citizenship and inequality."}, {"id": "bf3e8664-6cd9-4827-bdfa-d51cb0664504", "type": "subtopic", "title": "Corruption, informality, and legitimacy", "children": [{"id": "53c2035b-415b-48f9-8768-717a6d9a1774", "type": "concept", "title": "Corruption"}, {"id": "db757f2b-9038-413c-9a30-6fa08571d450", "type": "concept", "title": "Patronage"}, {"id": "6cc11fc7-10ff-4aba-9c5a-f1d90de6f4bb", "type": "concept", "title": "Clientelism"}, {"id": "10aa8655-c69c-40ca-a1db-e257a76fa8c1", "type": "concept", "title": "Bribery"}, {"id": "d5ca589e-d3bd-44b2-91e7-4a1523c94a0c", "type": "concept", "title": "Informality"}, {"id": "44d9aeb3-0d98-4c3f-8cc5-5dae3b7c33c3", "type": "concept", "title": "Legitimacy"}], "description": "Students analyze corruption and informality as moral and political categories, not merely failures of governance."}]}, {"id": "1b89be11-3bbb-4d71-99a1-ff991292dca9", "type": "topic", "title": "Law, Sovereignty, Citizenship, and Rights", "description": "Connects political authority to legal pluralism, citizenship regimes, rights claims, documentation, borders, and belonging.", "children": [{"id": "c5674ca5-e113-45b2-b56e-a07e5bcd8c6e", "type": "subtopic", "title": "Legal pluralism", "children": [{"id": "0da28a4c-175e-46bb-8ca9-b1f28ca60b3c", "type": "concept", "title": "Customary law"}, {"id": "568ec063-ef68-422d-a9eb-412936e53a03", "type": "concept", "title": "State law"}, {"id": "6307e30d-0e6e-419c-a46c-165e1b42c881", "type": "concept", "title": "Religious law"}, {"id": "5b39bd27-1737-46a9-a0d9-d16d7bad3f10", "type": "concept", "title": "Plural jurisdiction"}, {"id": "9e1cdcf2-7cb7-4cd0-9472-7716d3f3f299", "type": "concept", "title": "Forum shopping"}, {"id": "3dbefa88-fcce-41eb-b446-8c5d977bf4ea", "type": "concept", "title": "Legal consciousness"}], "description": "Students learn how state law coexists with customary law, religious law, community norms, and transnational legal orders."}, {"id": "851cf0bd-d53c-4cd1-bf71-86726c49e5c2", "type": "subtopic", "title": "Citizenship and documentation", "children": [{"id": "0d17e1d3-e669-4d1f-ae92-5232237f8f3a", "type": "concept", "title": "Citizenship"}, {"id": "08bb8fcc-0ad1-4bd6-9cde-b6a954d8d6dc", "type": "concept", "title": "Statelessness"}, {"id": "0619679c-71ec-4322-a421-754f64a60ac2", "type": "concept", "title": "Passport"}, {"id": "940a32fa-e94b-4a2f-924f-f00e3d55ef0f", "type": "concept", "title": "ID documents"}, {"id": "9c20e54a-fd2b-458c-992c-2d22877dd277", "type": "concept", "title": "Birth registration"}, {"id": "d87f36a3-16e5-41de-b20f-e247e1313528", "type": "concept", "title": "Denizenship"}], "description": "This subtopic examines how papers, IDs, passports, and registries create inclusion and exclusion."}, {"id": "dfc1c98e-7080-4e75-ae75-d93574c65dfb", "type": "subtopic", "title": "Rights claims and sovereignty", "children": [{"id": "ac4da2d5-05f0-4fbb-a016-dc27247ee960", "type": "concept", "title": "Human rights"}, {"id": "9809afaa-8d46-49b8-a3e5-0bbeae858889", "type": "concept", "title": "Indigenous rights"}, {"id": "e93dfd51-cff4-41e7-a26b-be2dc63de94d", "type": "concept", "title": "Sovereignty"}, {"id": "1f13677d-4b00-44cc-b34d-940e7b083876", "type": "concept", "title": "Self-determination"}, {"id": "c6f4cd28-aad8-4820-af73-56a95874a5aa", "type": "concept", "title": "Legal mobilization"}, {"id": "95f653a2-f61c-4301-872d-f49698019ecc", "type": "concept", "title": "Recognition"}], "description": "Students analyze how groups mobilize rights language while confronting state, corporate, and colonial power."}]}, {"id": "071ba991-d801-430d-ae13-aac743655d90", "type": "topic", "title": "Inequality, Class, Caste, Race, and Social Difference", "description": "Places inequality at the center of economic and political life, emphasizing historically produced and intersectional forms of domination.", "children": [{"id": "df965d9a-10ba-4d28-b393-3623b08dc98f", "type": "subtopic", "title": "Class and political economy", "children": [{"id": "e40fd1e3-941b-44e0-82cd-f969aa846f53", "type": "concept", "title": "Class formation"}, {"id": "413f771e-08c8-42fe-bddb-c9ae2c5481c7", "type": "concept", "title": "Proletarianization"}, {"id": "9fa645da-f7cb-4c84-bf39-8e0f7741fd79", "type": "concept", "title": "Petty commodity production"}, {"id": "8099752c-2c7c-4c0e-b20f-6914f39668e7", "type": "concept", "title": "Middle class"}, {"id": "1a4ce6d2-6d7e-4861-a955-cf3e7aab66de", "type": "concept", "title": "Precarity"}, {"id": "e6284e20-99bf-4557-a5da-9c1b35a5ce4b", "type": "concept", "title": "Elite reproduction"}], "description": "Students learn to connect labor, property, consumption, education, debt, and state policy to class formation."}, {"id": "a75637a8-5563-41ab-bcc8-35edd113038a", "type": "subtopic", "title": "Caste, race, and racial capitalism", "children": [{"id": "a383a98b-c66f-4410-b532-f780f04bda02", "type": "concept", "title": "Caste"}, {"id": "ed4782a4-343e-48b0-8cd8-0787c9e57f60", "type": "concept", "title": "Race"}, {"id": "ffbb451b-c396-41a4-a483-e52f8865412c", "type": "concept", "title": "Racial capitalism"}, {"id": "a70c72c5-0b59-4e5e-bb44-bcae2917473d", "type": "concept", "title": "Colonial labor"}, {"id": "30d61719-9831-4d65-8d0e-5c987c807333", "type": "concept", "title": "Segregation"}, {"id": "9370e965-c372-43da-abd6-ad0ca480418d", "type": "concept", "title": "Extraction"}], "description": "This subtopic analyzes how hierarchy becomes naturalized through labor regimes, property, colonialism, and social classification."}, {"id": "8685adbb-c327-4147-8d1d-a7480e4c6b46", "type": "subtopic", "title": "Intersectional inequality", "children": [{"id": "6b44d541-418f-4fc5-bce0-64e6fd26629e", "type": "concept", "title": "Intersectionality"}, {"id": "e1adf624-05ab-415c-b3f9-10fc28398f8c", "type": "concept", "title": "Gendered labor"}, {"id": "cc45088f-5831-4bb9-969a-2e177282cb2f", "type": "concept", "title": "Migrant status"}, {"id": "0a50dedc-f811-45a5-bcf7-819d99114e68", "type": "concept", "title": "Disability"}, {"id": "68b20654-9e97-4eb0-8c4f-c56dad55c82b", "type": "concept", "title": "Age"}, {"id": "e38f2a37-a5ea-4144-a313-d0068e02ba4a", "type": "concept", "title": "Vulnerability"}], "description": "Students examine how gender, sexuality, migration, disability, age, and citizenship shape access to resources and protection."}]}, {"id": "9fc9182d-4c50-4dfb-89f0-1f478c8b46d6", "type": "topic", "title": "Violence, Conflict, Security, and Militarization", "description": "Studies violence as political, economic, symbolic, structural, and intimate, while examining security as a field of governance.", "children": [{"id": "3e0e5dc7-166c-401c-9621-eba5ba575c58", "type": "subtopic", "title": "Forms of violence", "children": [{"id": "f27cb99d-13ed-4ff1-9303-78852767903e", "type": "concept", "title": "Structural violence"}, {"id": "610a512e-a4bd-4d43-823e-c2191cbf5993", "type": "concept", "title": "Symbolic violence"}, {"id": "2145e3c6-cfb8-4284-895d-06bf0e6fda5b", "type": "concept", "title": "Slow violence"}, {"id": "44c88d13-22fb-45a2-af35-c68918c6a021", "type": "concept", "title": "Everyday violence"}, {"id": "9accd919-4aac-4048-b175-c1f052a95525", "type": "concept", "title": "Intimate violence"}, {"id": "1bda5338-2fb0-4f12-956d-f2570100b8f6", "type": "concept", "title": "State violence"}], "description": "Students distinguish direct violence from structural, symbolic, slow, and everyday violence."}, {"id": "0ff149c8-21fa-4774-86bc-d9df9a1c7cb2", "type": "subtopic", "title": "Security and militarization", "children": [{"id": "9f95720e-af16-415a-b273-239bc04b46ff", "type": "concept", "title": "Militarization"}, {"id": "91402f0d-3f9f-4b5f-8a98-f3535a0b5290", "type": "concept", "title": "Policing"}, {"id": "baf4400b-774d-48c2-a73a-c8f2f3edf980", "type": "concept", "title": "Surveillance"}, {"id": "4b97e1da-1c06-4920-b166-b7c7a1610efd", "type": "concept", "title": "Counterinsurgency"}, {"id": "82201138-958e-46fc-b655-f6e83cb6ef2c", "type": "concept", "title": "Border security"}, {"id": "c5b9d26e-d10d-48e7-9553-35995bc5a23d", "type": "concept", "title": "Private security"}], "description": "This subtopic explores policing, borders, counterinsurgency, surveillance, and security economies."}, {"id": "15a178fb-ea85-43ef-b4aa-98057bf626d7", "type": "subtopic", "title": "Conflict economies", "children": [{"id": "98e4faa3-7262-4d75-b480-866c66034506", "type": "concept", "title": "War economy"}, {"id": "54977e2d-0b7c-41f0-ade6-23818a6dd5f9", "type": "concept", "title": "Displacement"}, {"id": "c9d01434-123e-4a79-970c-2189c1dcecf4", "type": "concept", "title": "Looting"}, {"id": "fdb25445-4a7e-451d-960e-7d18cc598f3d", "type": "concept", "title": "Smuggling"}, {"id": "9706830a-a378-4965-ab72-c7f683be55b9", "type": "concept", "title": "Reconstruction"}, {"id": "d4839132-561b-46db-a37a-b768c04af7ca", "type": "concept", "title": "Resource conflict"}], "description": "Students analyze how war, displacement, extraction, aid, smuggling, and reconstruction create political-economic systems."}]}, {"id": "3bdcefee-819d-4c8a-b07e-89252620bdf6", "type": "topic", "title": "Neoliberalism, Globalization, and Precarity", "description": "Examines how market-oriented reform and global integration reshape subjectivity, labor, welfare, risk, and political imagination.", "children": [{"id": "7a395e4d-45d6-496e-ac9f-4212ceecdc38", "type": "subtopic", "title": "Neoliberal governance", "children": [{"id": "c5da104b-3073-46ae-9fd8-8cc125102e4d", "type": "concept", "title": "Privatization"}, {"id": "f927f8f9-c8d4-4355-9e93-98ee0e1c6fa6", "type": "concept", "title": "Deregulation"}, {"id": "99a1270b-30c2-4907-90df-16b8172bedb3", "type": "concept", "title": "Entrepreneurial self"}, {"id": "71f5a1e7-a2e3-4580-ae08-dc7d0b77200e", "type": "concept", "title": "Responsibilization"}, {"id": "8295b1cb-c685-472c-89c6-3489ce06da4b", "type": "concept", "title": "Audit culture"}, {"id": "74b3ee0b-1b29-4a6f-b839-e5f64b4facb4", "type": "concept", "title": "Austerity"}], "description": "Students learn how market rationalities reorganize state responsibility, citizenship, and selfhood."}, {"id": "63c9c563-e84e-4f58-8a41-f213c5882b77", "type": "subtopic", "title": "Global flows and supply chains", "children": [{"id": "8c5d134e-3b03-4984-b448-ba61ed80b8eb", "type": "concept", "title": "Supply chain"}, {"id": "645f43b8-269d-42cf-89bd-47211a2dae68", "type": "concept", "title": "Outsourcing"}, {"id": "1a8d2b37-62b1-4227-89f2-016203fc6042", "type": "concept", "title": "Logistics"}, {"id": "1e817fc9-bc12-4325-861e-225dd1153289", "type": "concept", "title": "Commodity chain"}, {"id": "cf48efec-a7d3-4363-b44c-4d0dd2bc42bb", "type": "concept", "title": "Export processing zone"}, {"id": "5e617867-d621-4c2e-adda-1c748f821032", "type": "concept", "title": "Global labor"}], "description": "This subtopic connects local livelihoods to transnational production, logistics, finance, and commodity circulation."}, {"id": "4de24717-0276-48b7-b491-c669d6419771", "type": "subtopic", "title": "Precarity and risk", "children": [{"id": "56baae46-d937-4cf6-986f-da910572cd4a", "type": "concept", "title": "Precarity"}, {"id": "71d9430a-1e9d-4e7b-9ec8-be9a49a50f63", "type": "concept", "title": "Risk"}, {"id": "94bb6473-030c-491e-88b2-bd3404bca7a9", "type": "concept", "title": "Informal work"}, {"id": "b3f36cba-bf5f-4ef9-a03e-4cdf3ee59402", "type": "concept", "title": "Gig economy"}, {"id": "f439d514-f414-424c-bded-8a3961709e95", "type": "concept", "title": "Flexibilization"}, {"id": "bd872bc6-b3d2-4c64-a95f-dbc79ec7e378", "type": "concept", "title": "Survival strategy"}], "description": "Students analyze insecurity as a normal condition produced by labor markets, debt, migration, climate, and policy."}]}, {"id": "bc8ecbaf-8b07-455e-a2f9-e03d833fc614", "type": "topic", "title": "Extraction, Environment, and Resource Politics", "description": "Connects political economy to oil, mining, water, forests, fisheries, carbon, infrastructure, toxicity, and environmental justice.", "children": [{"id": "67bef7be-1b61-43cc-9d14-204f3d412eb7", "type": "subtopic", "title": "Resource extraction", "children": [{"id": "e50970e1-4e8a-42cf-8bd9-8dee764ba4f4", "type": "concept", "title": "Mining"}, {"id": "63cfd78f-541e-4ac4-b7fe-8808a5c03624", "type": "concept", "title": "Oil"}, {"id": "023f965f-55ec-48de-9afb-75d3e9331eb1", "type": "concept", "title": "Timber"}, {"id": "b842c85c-1607-4666-b246-a5ec337df28a", "type": "concept", "title": "Water"}, {"id": "8315e85e-3acf-46b1-9b5e-d88893049ecd", "type": "concept", "title": "Concession"}, {"id": "a21bc89d-f008-4fe3-96fd-d6c157635114", "type": "concept", "title": "Resource curse"}], "description": "Students examine how extractive projects reorganize land, labor, sovereignty, and social relations."}, {"id": "e6a8c5d5-2dd9-4eb7-a556-3b48b4b0bff8", "type": "subtopic", "title": "Infrastructure and logistics", "children": [{"id": "adfaebf5-c191-4efe-803f-861e4dea5618", "type": "concept", "title": "Infrastructure"}, {"id": "c5e85287-8d7b-432c-93ca-a2e79955f0c8", "type": "concept", "title": "Corridor"}, {"id": "f27c989e-1935-47f7-b253-4e8f8625aa91", "type": "concept", "title": "Pipeline"}, {"id": "4713bfa1-2a43-4657-bc28-bc73ea574b38", "type": "concept", "title": "Dam"}, {"id": "f1fbf4e2-9ba0-40f1-b15b-31366000d12a", "type": "concept", "title": "Port"}, {"id": "1d2f5311-8803-4330-9d17-6ec52bb11fc6", "type": "concept", "title": "Maintenance"}], "description": "This subtopic studies roads, ports, dams, pipelines, grids, and corridors as political-economic projects."}, {"id": "05d8b64f-afe6-47ca-bfa1-0ba4a1b2cd03", "type": "subtopic", "title": "Environmental justice", "children": [{"id": "b59c76ca-1c1f-4901-ae61-5b012316d9a1", "type": "concept", "title": "Toxicity"}, {"id": "bb805cec-b9ce-4876-9fe8-3ec2bc2114fe", "type": "concept", "title": "Sacrifice zone"}, {"id": "dee1b7b5-324a-4bc5-b7d2-ade7bff350b4", "type": "concept", "title": "Climate justice"}, {"id": "a594e0a6-1998-4473-a982-f0beb57e7623", "type": "concept", "title": "Commons"}, {"id": "7b4212d5-7c3c-4c90-8e8a-4ecdb9a3717a", "type": "concept", "title": "Conservation displacement"}, {"id": "17596412-685e-4036-b3f3-915b69e6ba99", "type": "concept", "title": "Indigenous stewardship"}], "description": "Students analyze uneven exposure to harm and unequal access to environmental decision-making."}]}, {"id": "7381ce40-2afd-488c-aed3-d7ef391a6bfb", "type": "topic", "title": "Social Movements, Resistance, and Collective Action", "description": "Explores how people contest inequality, dispossession, state violence, exploitation, debt, austerity, and environmental harm.", "children": [{"id": "bd00ca4f-85b8-40ef-a463-dbd50dd6554b", "type": "subtopic", "title": "Everyday resistance and refusal", "children": [{"id": "3a80528b-caa9-46e6-a5f6-57ef46a70f33", "type": "concept", "title": "Hidden transcript"}, {"id": "57296e14-0ab7-4998-b594-c417a40b42a6", "type": "concept", "title": "Foot-dragging"}, {"id": "c143e555-77c4-45e3-b5a6-30855cbbcb95", "type": "concept", "title": "Refusal"}, {"id": "bcacbf75-d882-4188-b55e-fdb994d28d1e", "type": "concept", "title": "Evasion"}, {"id": "f2720ebb-07c4-4386-94de-059d53298e05", "type": "concept", "title": "Moral economy"}, {"id": "54af772f-92b1-462d-8202-29819350e056", "type": "concept", "title": "Counter-conduct"}], "description": "Students learn why resistance often appears as evasion, sabotage, refusal, silence, or alternative livelihood."}, {"id": "e60003e9-5ef8-4dc7-874c-0e8f7d9e20b0", "type": "subtopic", "title": "Movements and mobilization", "children": [{"id": "a0a2fed8-2adb-4063-86c3-1b221e19af28", "type": "concept", "title": "Mobilization"}, {"id": "142c6e5b-c38f-4e05-9d4d-fcbaee41bc47", "type": "concept", "title": "Framing"}, {"id": "56669a28-8149-4199-b1af-ee5bf88e5e34", "type": "concept", "title": "Repertoires"}, {"id": "017f4881-32cb-45a9-8426-be75427a3a3e", "type": "concept", "title": "Solidarity"}, {"id": "0b409c7f-e802-44c6-abfa-d0598fd44158", "type": "concept", "title": "Coalition"}, {"id": "27069d0e-893a-442f-b5db-8ee725be25ad", "type": "concept", "title": "Leadership"}], "description": "This subtopic examines how organizations, networks, emotions, symbols, and grievances become collective action."}, {"id": "524c7696-9749-4351-b70e-4894caeda776", "type": "subtopic", "title": "Prefigurative and alternative economies", "children": [{"id": "abc912bc-dc03-4813-98bd-13e6e9fc481e", "type": "concept", "title": "Cooperatives"}, {"id": "81fc6cfe-18d1-4a93-98d1-854532b9eee4", "type": "concept", "title": "Mutual aid"}, {"id": "2d0b2fb6-dc22-4aeb-943b-36e67a68a92a", "type": "concept", "title": "Commons"}, {"id": "730755d3-7d58-4d99-a2e2-1d69ea1bb164", "type": "concept", "title": "Solidarity economy"}, {"id": "180ccc8b-ebb6-4e14-aeb4-8fcb94e232d1", "type": "concept", "title": "Worker ownership"}, {"id": "911613cd-105a-4527-a2fd-f9b97b514621", "type": "concept", "title": "Autonomy"}], "description": "Students analyze attempts to build economic and political alternatives in the present."}]}, {"id": "a8398f9f-71ce-49be-a893-debbcb773c66", "type": "topic", "title": "Ethnographic Methods for Power and Economy", "description": "Gives students practical methods for studying institutions, transactions, documents, networks, budgets, work, and political claims.", "children": [{"id": "1cb5e9f2-4574-4fe4-adfd-8cc3f640ed6e", "type": "subtopic", "title": "Following people, things, and money", "children": [{"id": "eebca19e-2a6f-41e6-a289-a80c56fbe316", "type": "concept", "title": "Multi-sited ethnography"}, {"id": "667a872d-61fe-479d-9811-bd2ee11f7317", "type": "concept", "title": "Commodity tracing"}, {"id": "38c85370-b430-4dc1-98b4-bd363f3a75a7", "type": "concept", "title": "Follow the money"}, {"id": "4505030d-010a-45b9-be54-2b2aefa418b8", "type": "concept", "title": "Network mapping"}, {"id": "f0f63d5d-9f07-4abd-a83b-dfea2a52661a", "type": "concept", "title": "Document trail"}, {"id": "c738d856-b01a-4190-bfed-319eb1ba7f50", "type": "concept", "title": "Institutional ethnography"}], "description": "Students learn multi-sited techniques for tracking flows and relations across places and institutions."}, {"id": "66ba5d4a-24bd-4ed0-9a0a-eddca70d3b04", "type": "subtopic", "title": "Studying elites and institutions", "children": [{"id": "118cd21f-b1d9-4893-ba95-bbba3a8badfa", "type": "concept", "title": "Elite interviews"}, {"id": "84020631-ccd3-493d-b6e3-733dda83a7af", "type": "concept", "title": "Access"}, {"id": "0bd1af53-faf5-4fd5-8f1d-54bf366d6de7", "type": "concept", "title": "Gatekeepers"}, {"id": "55b6b1bd-e35f-47df-97ee-dc2f115d0088", "type": "concept", "title": "Archives"}, {"id": "ee7554bb-0eb0-4225-a241-0a2c9e39538c", "type": "concept", "title": "Meetings"}, {"id": "f24417e4-eb0b-487c-8252-0d28e755947a", "type": "concept", "title": "Organizational charts"}], "description": "This subtopic prepares students to research powerful actors, opaque organizations, and bureaucratic settings."}, {"id": "7d9a6444-aa70-4f0d-ab07-ae3e4e6e48fd", "type": "subtopic", "title": "Ethics and risk in political-economic research", "children": [{"id": "6339b3a9-7b91-4cec-9d2a-f0907d040b7e", "type": "concept", "title": "Informed consent"}, {"id": "9bdedfcc-3cc7-4d0d-bdf9-442c2ead88fe", "type": "concept", "title": "Anonymization"}, {"id": "bb9c3da9-0b39-4699-9675-ba230f9e3b6a", "type": "concept", "title": "Data security"}, {"id": "cd5d9137-0797-4c3a-be17-9af26dd6a9da", "type": "concept", "title": "Retaliation risk"}, {"id": "6c71ce1d-251f-4807-ad51-d739835736e8", "type": "concept", "title": "Do no harm"}, {"id": "dbc56822-416d-4b72-bb1e-a63449389940", "type": "concept", "title": "Reciprocity"}], "description": "Students consider consent, confidentiality, security, retaliation, and researcher responsibility."}]}, {"id": "2041fe64-6bdc-44df-bf93-5be594255017", "type": "topic", "title": "Capstone: Ethnographic Analysis of Power", "description": "Synthesizes course concepts through a focused research project that explains an economic or political process using anthropological evidence.", "children": [{"id": "413d69c2-4cbf-46b4-a3c1-d2519852e5a5", "type": "subtopic", "title": "Building a case study", "children": [{"id": "de352a4e-a0be-44ed-a488-82b8b87218ac", "type": "concept", "title": "Research question"}, {"id": "bf7a7e09-7548-4d71-80ec-405d8620f25c", "type": "concept", "title": "Actor map"}, {"id": "351057fc-d10c-4e04-9995-33d606d52878", "type": "concept", "title": "Institutional map"}, {"id": "5647d970-fe47-4b36-8641-65aff4c64c04", "type": "concept", "title": "Fieldnotes"}, {"id": "0e5ad17a-eb8f-4a85-a5b0-50e20440173b", "type": "concept", "title": "Document analysis"}, {"id": "4c4ef726-4fd6-4bd1-98cc-b3ce17c5235b", "type": "concept", "title": "Evidence matrix"}], "description": "Students define a research question, identify actors, map institutions, and choose evidence."}, {"id": "d6f2eca5-790f-4f8a-9bbe-0c0c75c29638", "type": "subtopic", "title": "Developing an argument", "children": [{"id": "7ffabd9e-2419-4495-894e-066ef50f4a05", "type": "concept", "title": "Analytic memo"}, {"id": "9de25aad-ce67-4634-b819-b803cacdd372", "type": "concept", "title": "Concept application"}, {"id": "50efe484-d04d-4184-a51f-b6d190673369", "type": "concept", "title": "Counterargument"}, {"id": "d8575772-3391-4b4e-a038-d4d8e5f23484", "type": "concept", "title": "Causal caution"}, {"id": "00fc23a3-5881-43fa-a2c5-f948dcabcd55", "type": "concept", "title": "Triangulation"}, {"id": "21b854bd-5c0d-4d5f-896f-6100252fefd5", "type": "concept", "title": "Thesis statement"}], "description": "This subtopic turns observations and readings into a claim about power, exchange, inequality, or governance."}, {"id": "0f024a0b-edb0-4684-afe4-79025c93dcfc", "type": "subtopic", "title": "Public anthropology product", "children": [{"id": "5d94715d-72f2-45dc-bc25-4412c5ae1cba", "type": "concept", "title": "Policy brief"}, {"id": "92eccdc7-3f9a-4095-80f6-c05d9915205c", "type": "concept", "title": "Public essay"}, {"id": "da865a2d-4b9d-4642-a611-68b0327e25e0", "type": "concept", "title": "Podcast script"}, {"id": "b95c1925-2bc7-45ba-beb8-3c2579b421dd", "type": "concept", "title": "Data vignette"}, {"id": "b184f889-2273-4d02-9f4d-9fb742eb5b24", "type": "concept", "title": "Presentation"}, {"id": "f8a3324a-9201-49e4-8427-22798f353800", "type": "concept", "title": "Ethical representation"}], "description": "Students translate research into a clear output for readers beyond the classroom."}]}], "dbBacked": true}$epanjson$::jsonb,
