update public.learning_paths
set
  title = 'Economic / Political Anthropology',
  goal = 'Economic / Political Anthropology',
  summary = 'This course studies how people organize material life and political authority across diverse societies and global systems. Students examine exchange, labor, money, debt, property, development, bureaucracy, law, sovereignty, inequality, violence, neoliberalism, extraction, and social movements through ethnographic and theoretical lenses. The syllabus centers on power, value, obligation, and evidence through a granular anthropology outline.',
  data = $epanjson${"slug": "economic-political-anthropology", "title": "Economic / Political Anthropology", "description": "This course studies how people organize material life and political authority across diverse societies and global systems. Students examine exchange, labor, money, debt, property, development, bureaucracy, law, sovereignty, inequality, violence, neoliberalism, extraction, and social movements through ethnographic and theoretical lenses. The syllabus centers on power, value, obligation, and evidence through a granular anthropology outline.", "topics": [{"id": "01e6557d-633d-4168-8d86-e2a16a6972fc", "type": "topic", "title": "Economic and Political Anthropology as a Field", "description": "Introduces the course's central problem: how humans organize livelihood, value, exchange, authority, coercion, obligation, and inequality in culturally specific but globally connected ways.", "children": [{"id": "d0955a08-1a60-4e5d-b3bc-12ccf6fa5bf1", "type": "subtopic", "title": "Core questions and analytic scale", "children": [{"id": "04a5850a-7c1c-42c6-b408-47f230d1813b", "type": "concept", "title": "Livelihood"}, {"id": "aca67dba-987b-4d4f-9266-7ff1928884de", "type": "concept", "title": "Value"}, {"id": "7b75b96f-7d28-4138-9f72-3b461c0e300b", "type": "concept", "title": "Authority"}, {"id": "df3fee3d-5851-4fcb-b6a6-765832468c56", "type": "concept", "title": "Power"}, {"id": "f7618e99-c845-4cf2-bf5a-a6d7d47ee56c", "type": "concept", "title": "Scale"}, {"id": "d0b0e5f2-6736-4635-a815-fcb103dcb3f2", "type": "concept", "title": "Embeddedness"}], "description": "Students learn to ask how household life, markets, states, empires, and global systems connect rather than treating economy and politics as separate boxes."}, {"id": "f698dda9-f754-4f0c-975f-2f503c756601", "type": "subtopic", "title": "Economy and politics as cultural systems", "children": [{"id": "c45f0ec0-7111-47c7-9243-6207622cf77a", "type": "concept", "title": "Moral order"}, {"id": "611c7256-3a04-417d-a019-cbec91efc180", "type": "concept", "title": "Institution"}, {"id": "0fcbed94-fa2c-458e-82b0-a985bad54553", "type": "concept", "title": "Practice"}, {"id": "2dc2f3eb-5426-4267-bb6f-bef6d9d66143", "type": "concept", "title": "Personhood"}, {"id": "27cb2c6d-fbdd-434d-858f-88e3b62656ff", "type": "concept", "title": "Obligation"}, {"id": "8fb8e659-2cfc-42ab-bbcb-34a7f9a7b2e5", "type": "concept", "title": "Legitimacy"}], "description": "This subtopic shows why anthropologists study money, markets, states, and law as moral and symbolic orders as well as institutions."}, {"id": "b1fb048c-c5ec-4595-8528-57216d06f101", "type": "subtopic", "title": "Ethnography of power and exchange", "children": [{"id": "3c0af639-7da1-4d11-b00d-c9b2c8850c79", "type": "concept", "title": "Participant observation"}, {"id": "f18e36d5-810e-43f4-830b-abe2d7304a08", "type": "concept", "title": "Fieldsite"}, {"id": "27435362-37e9-442b-a10b-48bcec6af5ec", "type": "concept", "title": "Thick description"}, {"id": "5bbf8fb4-d751-4a40-99bd-96869d731b53", "type": "concept", "title": "Everyday politics"}, {"id": "1646effa-f00a-473b-a2cb-cf636fca7933", "type": "concept", "title": "Relational analysis"}, {"id": "b2b0a0ff-49d4-4d91-a825-360f6409673b", "type": "concept", "title": "Historical context"}], "description": "Students see how fieldwork reveals informal, everyday, and contested dimensions of economic and political life."}]}, {"id": "15dd8c0f-4929-4ef4-bbe0-56b089875c8b", "type": "topic", "title": "Gift, Commodity, and Exchange Theory", "description": "Builds from classic exchange theory to modern debates about reciprocity, obligation, commodity circulation, and social relationships.", "children": [{"id": "7463419f-a1bb-4b70-bbf1-bab5f94a4a20", "type": "subtopic", "title": "The gift and reciprocity", "children": [{"id": "f9c6d52c-4c69-4280-9734-bcce4bd86ad6", "type": "concept", "title": "Mauss"}, {"id": "537b109c-dce0-4291-95c5-a2bf648bc763", "type": "concept", "title": "Reciprocity"}, {"id": "ae1c189f-9ab2-41ac-961e-45d49e438792", "type": "concept", "title": "Obligation to give"}, {"id": "759c4ba3-5d3b-4b47-8b49-873dab5b6ab2", "type": "concept", "title": "Obligation to receive"}, {"id": "11164b07-429c-4b5f-9de3-9fc0c5aa2858", "type": "concept", "title": "Obligation to return"}, {"id": "ab51bac6-554d-4504-8116-93cf0979e4cf", "type": "concept", "title": "Prestige"}], "description": "The point is to understand exchange as relationship-making, not merely transfer of goods."}, {"id": "24aa4a28-ab11-447a-a739-76b586f4b9f9", "type": "subtopic", "title": "Commodity exchange and alienability", "children": [{"id": "c9aac3a4-1964-4b82-82a3-62d29158b7ca", "type": "concept", "title": "Commodity"}, {"id": "fd3646b4-e57d-4384-9485-ea47f0fb8ebc", "type": "concept", "title": "Alienability"}, {"id": "c8fe5c38-e56e-48f9-8670-926826592897", "type": "concept", "title": "Use value"}, {"id": "b0bdc5e6-fc66-4884-b235-db64cf331738", "type": "concept", "title": "Exchange value"}, {"id": "21c2ca89-bac2-443d-bcec-d3c81def4c39", "type": "concept", "title": "Commodification"}, {"id": "c4ab8394-a4d9-4083-b028-aaa4ef81ce4d", "type": "concept", "title": "Singularization"}], "description": "Students compare gifts and commodities by asking what is separable from persons, places, histories, and obligations."}, {"id": "964a6f67-d2cf-4c6d-b45e-09949fdec36b", "type": "subtopic", "title": "Exchange systems and social rank", "children": [{"id": "0a3c7e09-d552-40d9-81f2-fb36d19272fa", "type": "concept", "title": "Kula"}, {"id": "9a4363ad-3107-4d78-a804-1876d33431e0", "type": "concept", "title": "Potlatch"}, {"id": "362220ca-d3c7-4455-9983-0083d1b22561", "type": "concept", "title": "Bridewealth"}, {"id": "996b98e3-4a50-470e-852b-24c0e5a30013", "type": "concept", "title": "Dowry"}, {"id": "5f2beb74-315b-4ae9-bf41-e6af7e97146b", "type": "concept", "title": "Redistribution"}, {"id": "cfa3dac5-acaf-4aac-bc3b-c130b22f73ec", "type": "concept", "title": "Rank"}], "description": "This subtopic links exchange to hierarchy, alliance, rivalry, ritual, and redistribution."}]}, {"id": "8d35c481-6e97-47e2-99b4-2045bae3d5f3", "type": "topic", "title": "Labor, Value, and Household Economies", "description": "Examines how work, production, care, subsistence, kinship, and households organize economic life beyond formal wage labor.", "children": [{"id": "d25a9022-7da1-4ffc-9b57-01a58b8f60ea", "type": "subtopic", "title": "Labor and value", "children": [{"id": "93e8dd9d-9d7d-4bb5-af44-1559802ec7ec", "type": "concept", "title": "Labor power"}, {"id": "49d8292b-abff-4b97-971c-957373e66425", "type": "concept", "title": "Surplus"}, {"id": "d673ccc7-bb39-4e28-bae4-c056676d3e5e", "type": "concept", "title": "Value regimes"}, {"id": "d78b63f7-f65a-4b7f-929d-7ab7c3166c19", "type": "concept", "title": "Use value"}, {"id": "16054402-9b52-485e-9280-d0fbd81eca34", "type": "concept", "title": "Socially necessary labor"}, {"id": "aa354af8-b4f9-47dd-9e7e-e6d924aa21b3", "type": "concept", "title": "Exploitation"}], "description": "Students learn how anthropologists analyze value as produced through work, social relations, scarcity, morality, and recognition."}, {"id": "5f9275ad-e6e9-4dee-9861-0eeeaa6428d6", "type": "subtopic", "title": "Household and kin-based economies", "children": [{"id": "569b8e1d-063b-4edb-820f-24f8b121361d", "type": "concept", "title": "Domestic mode of production"}, {"id": "698ed505-1b02-464a-a455-a091b03befe3", "type": "concept", "title": "Household strategy"}, {"id": "065dc4e8-07ad-463b-a3b4-4886cdd049a6", "type": "concept", "title": "Kin obligations"}, {"id": "fb33e5b2-2bc6-439e-a4da-6e0c79e7266a", "type": "concept", "title": "Gendered labor"}, {"id": "fe5757d6-aa97-4d90-b413-e5597d155a23", "type": "concept", "title": "Subsistence"}, {"id": "747ac863-51e3-4ac2-82f5-bd841105cfdb", "type": "concept", "title": "Informal economy"}], "description": "This subtopic explains how families, kin groups, and households allocate work, risk, food, income, and care."}, {"id": "281b6b2d-2176-4815-b782-2cbbd97dcb8d", "type": "subtopic", "title": "Care, reproduction, and hidden work", "children": [{"id": "fcc9f57e-6028-49ff-b1e0-7dd68c63a037", "type": "concept", "title": "Social reproduction"}, {"id": "90b99120-7353-40ff-85c7-49741664ec21", "type": "concept", "title": "Care work"}, {"id": "81274c4c-30c1-4cfd-9d43-3dbea79946b1", "type": "concept", "title": "Emotional labor"}, {"id": "3f8e463d-fec9-49d1-a998-c82ceec33cf3", "type": "concept", "title": "Reproductive labor"}, {"id": "1acd741b-c959-424b-b7e1-45a949ab9c61", "type": "concept", "title": "Interdependence"}, {"id": "c8c21cd1-72bc-4b56-8681-3f6eef57cf81", "type": "concept", "title": "Time poverty"}], "description": "Students examine the economic importance of caregiving, social reproduction, emotional labor, and unpaid labor."}]}, {"id": "fff82dca-813e-4ea2-a4b1-7a3ccf33bd31", "type": "topic", "title": "Markets, Money, and Moral Economies", "description": "Explores markets and money as moral, political, and culturally organized systems rather than neutral mechanisms.", "children": [{"id": "ba0f3453-b5d1-4207-8d1a-c0bc0fd8acec", "type": "subtopic", "title": "Embedded markets", "children": [{"id": "c7b010ff-2ccd-4600-9956-be6ee9dfdf95", "type": "concept", "title": "Polanyi"}, {"id": "eb37de3a-fba4-421e-b559-21623eee5bff", "type": "concept", "title": "Embeddedness"}, {"id": "632bd5b5-e454-4194-9418-336376481a85", "type": "concept", "title": "Market society"}, {"id": "24b08a00-127e-446d-bf89-46f2500d9c4c", "type": "concept", "title": "Reciprocity"}, {"id": "3577a1f1-65e4-458a-add3-d481c1ecfbcd", "type": "concept", "title": "Redistribution"}, {"id": "1a7eb3e8-6903-423c-aa6d-94d3209b0864", "type": "concept", "title": "Householding"}], "description": "Students learn Polanyi's insight that markets are always embedded in legal, moral, kinship, religious, and state arrangements."}, {"id": "7df29784-57b8-4674-99e1-82d350768c35", "type": "subtopic", "title": "Money and multiple currencies", "children": [{"id": "dcafb517-47ef-4c66-85d0-65c07b2611b7", "type": "concept", "title": "Earmarking"}, {"id": "4df4a28d-e473-4926-a1b5-d4174e377d71", "type": "concept", "title": "Special monies"}, {"id": "29530b7f-1fa9-4d83-ae63-d929f04523af", "type": "concept", "title": "Debt"}, {"id": "edefd413-6298-4d8f-87b1-712e491a011a", "type": "concept", "title": "Credit"}, {"id": "a6bc8403-a149-445a-b2a3-4bcdbeb8ba76", "type": "concept", "title": "Moral accounting"}, {"id": "9fc07250-14ce-4f62-adb1-f8eacfa504c2", "type": "concept", "title": "Currency plurality"}], "description": "This subtopic shows that money carries social meanings and can be earmarked, ranked, restricted, or morally contested."}, {"id": "e96fc86c-4356-4c41-bf32-292a028f1500", "type": "subtopic", "title": "Moral economy", "children": [{"id": "da7bb663-74c5-4e96-86e0-51f3889f8c8a", "type": "concept", "title": "E. P. Thompson"}, {"id": "81045ae8-28ad-4db2-80f5-0c8068fd0073", "type": "concept", "title": "James Scott"}, {"id": "cc0f5d7b-a034-45eb-bf0d-e430fc02d933", "type": "concept", "title": "Subsistence ethic"}, {"id": "5289ff82-341b-4f5c-b1d9-9d7e8bc8d150", "type": "concept", "title": "Just price"}, {"id": "857dc1e5-6b11-43ac-b138-3c887018a842", "type": "concept", "title": "Food riots"}, {"id": "d4e3e386-b656-4115-b63d-e3c0a8088dd5", "type": "concept", "title": "Moral outrage"}], "description": "Students analyze how communities define fairness, survival rights, just prices, and legitimate extraction."}]}, {"id": "3295a12d-ba8c-4a5f-816e-ed34ac1cd4de", "type": "topic", "title": "Debt, Credit, Finance, and Obligation", "description": "Traces debt as an economic relation, moral language, legal instrument, and political technology.", "children": [{"id": "8932ae70-5333-40ce-b873-7e49b045b2db", "type": "subtopic", "title": "Debt as social relation", "children": [{"id": "9a173924-ade0-49a2-91e3-35d51e10c455", "type": "concept", "title": "Creditor"}, {"id": "e8cd7bd4-2892-42e2-a42c-88cdc940a769", "type": "concept", "title": "Debtor"}, {"id": "85717454-6f6a-4e99-b292-5770116f8df1", "type": "concept", "title": "Obligation"}, {"id": "d758fd12-8b88-44ff-84a8-2883463873ee", "type": "concept", "title": "Reciprocity"}, {"id": "125de71f-8a24-43b4-8605-51065c98639c", "type": "concept", "title": "Honor"}, {"id": "a92f3377-8e7c-484b-996c-fd6888d441bd", "type": "concept", "title": "Bondage"}], "description": "Students learn how debt creates hierarchy, dependency, trust, memory, and obligation."}, {"id": "d2628b5e-9a97-415b-9238-083d3458338f", "type": "subtopic", "title": "Credit, microfinance, and development", "children": [{"id": "f9fae323-1ab5-4729-bf77-353fec58809a", "type": "concept", "title": "Microcredit"}, {"id": "a9b37505-347d-49ef-a65f-018cee574ba5", "type": "concept", "title": "Financial inclusion"}, {"id": "4c59ad9c-7561-4387-9e5f-96e838126685", "type": "concept", "title": "Group lending"}, {"id": "ee09fb43-d5f5-4ffe-9edc-f51fe8cfb0c0", "type": "concept", "title": "Interest"}, {"id": "d163a18d-7e6e-4674-8bc2-760c63147e5e", "type": "concept", "title": "Default"}, {"id": "6a340b88-c478-4cad-ada2-2718e373c67a", "type": "concept", "title": "Debt discipline"}], "description": "This subtopic examines the promises and problems of lending as anti-poverty policy."}, {"id": "f3e3aefd-5ca1-40db-b1a4-ce6706811ecb", "type": "subtopic", "title": "Financialization", "children": [{"id": "7ed7598a-21da-4e44-8111-9259de28b2d6", "type": "concept", "title": "Financialization"}, {"id": "7fac74dc-dd1b-4df1-97f6-bb21a65c4c86", "type": "concept", "title": "Assetization"}, {"id": "9ae0cd8b-e0dd-4df9-bdd3-aa445c9fdd8b", "type": "concept", "title": "Risk"}, {"id": "f1a0f672-c352-48de-a4fd-ab2af4b2c1df", "type": "concept", "title": "Speculation"}, {"id": "bd13279b-b217-457b-93ee-eee68679aebb", "type": "concept", "title": "Derivatives"}, {"id": "279d4032-6ca2-44d5-9965-d3983917a7b2", "type": "concept", "title": "Household debt"}], "description": "Students analyze how finance expands into housing, education, health, land, climate, and everyday life."}]}, {"id": "9bf40dc4-25bc-43b2-a770-7dbd950ee1e5", "type": "topic", "title": "Property, Land, Commons, and Dispossession", "description": "Studies how rights to land, resources, housing, territory, knowledge, and commons are made, defended, stolen, and transformed.", "children": [{"id": "f0d930f0-c2ce-4089-8790-bedb715bc898", "type": "subtopic", "title": "Property regimes", "children": [{"id": "2e3d1fe3-f888-4772-b09f-70e92137d551", "type": "concept", "title": "Private property"}, {"id": "1311dd76-a571-4197-a726-44e9d3e64b60", "type": "concept", "title": "Common property"}, {"id": "4b3f1400-9024-45c9-af1d-c6721f67d378", "type": "concept", "title": "Customary tenure"}, {"id": "5f1ff765-9016-4fd3-b8bd-2b8f22ebdf98", "type": "concept", "title": "State land"}, {"id": "8fd758f9-bfa6-41af-bd8d-4547050ebbcb", "type": "concept", "title": "Usufruct"}, {"id": "0a660c73-6238-4e69-8458-63f8b79a2115", "type": "concept", "title": "Enclosure"}], "description": "Students compare private, collective, state, customary, and common property systems."}, {"id": "d7c40cb1-2741-4159-9437-8c3c9bb938fa", "type": "subtopic", "title": "Land, territory, and sovereignty", "children": [{"id": "d49f7b27-5e7e-45a9-8d96-355f38dc59b5", "type": "concept", "title": "Territory"}, {"id": "b58ae850-1872-42a8-87cf-2ae8dba32b1b", "type": "concept", "title": "Sovereignty"}, {"id": "1904ae6c-0dd7-4c03-a358-1350e5347a26", "type": "concept", "title": "Land claims"}, {"id": "ffb1ad24-e410-4897-96aa-46acfbb18881", "type": "concept", "title": "Cadastral mapping"}, {"id": "2164730d-b955-48e6-809c-256dad3bfcff", "type": "concept", "title": "Settler colonialism"}, {"id": "ff314e35-1e3d-4f2c-85d7-f4688c2efe01", "type": "concept", "title": "Jurisdiction"}], "description": "This subtopic links property to Indigenous rights, colonialism, mapping, borders, and jurisdiction."}, {"id": "4c9e2b9f-698a-445b-a5b1-1a489a8c7bbe", "type": "subtopic", "title": "Accumulation by dispossession", "children": [{"id": "e5d77c05-6383-4361-afa1-4bc9f762bc44", "type": "concept", "title": "Dispossession"}, {"id": "d7bf3951-a55e-4372-b1bf-48d75cff3e38", "type": "concept", "title": "Primitive accumulation"}, {"id": "3a243112-8b60-4aab-a4af-2766fc3c58a4", "type": "concept", "title": "Eviction"}, {"id": "70d2e768-535e-454f-9fd7-e762883726dc", "type": "concept", "title": "Privatization"}, {"id": "0d72168e-861c-4bb1-92c0-74f2e28c53fb", "type": "concept", "title": "Resource extraction"}, {"id": "1f897006-4a8a-421c-b1b1-2536985af8cf", "type": "concept", "title": "Gentrification"}], "description": "Students analyze how wealth is made through enclosure, eviction, privatization, extraction, and legal coercion."}]}, {"id": "a1937a2d-af46-4ac2-853a-bf6ed1fc770d", "type": "topic", "title": "Development, Aid, and Humanitarianism", "description": "Critically examines development as a field of expertise, intervention, measurement, aspiration, dependency, and political contestation.", "children": [{"id": "9f704c6e-ea05-470c-80bd-1864f277217b", "type": "subtopic", "title": "Development discourse", "children": [{"id": "2e5110ab-9141-4273-b54e-33e84dbaa6c4", "type": "concept", "title": "Modernization"}, {"id": "4990fe56-7564-4806-bbcc-8ba9f4678980", "type": "concept", "title": "Underdevelopment"}, {"id": "40b454a9-cc97-46bf-a854-4c34745e3b14", "type": "concept", "title": "Expertise"}, {"id": "428b7292-6bbd-4f55-be04-feea8db29827", "type": "concept", "title": "Project cycle"}, {"id": "0e3dbc04-ba56-4e9f-9b5b-4df8a9a110a4", "type": "concept", "title": "Indicators"}, {"id": "ef64c304-8e45-4bc2-a0c2-0d57ef4532c5", "type": "concept", "title": "Beneficiary"}], "description": "Students learn how development categories define problems and authorize interventions."}, {"id": "9c09729a-f1ad-482b-ae91-8448665be331", "type": "subtopic", "title": "Aid institutions and NGOs", "children": [{"id": "6f957616-032a-4b76-afac-a9aa1df16561", "type": "concept", "title": "NGO"}, {"id": "414d83d0-1b18-4cff-acc9-e2853913e980", "type": "concept", "title": "Donor"}, {"id": "ebd2ba30-ed5a-4c9a-a52a-ce4f6b594301", "type": "concept", "title": "Capacity building"}, {"id": "cd19fe2f-6a8d-4507-b596-1085cc0c25ba", "type": "concept", "title": "Accountability"}, {"id": "cd23c074-bc71-447a-a392-602e7be610c2", "type": "concept", "title": "Audit"}, {"id": "d410864b-cbed-4a04-bebb-3c91c051326f", "type": "concept", "title": "Participation"}], "description": "This subtopic studies the everyday bureaucracy, ethics, and unintended effects of aid work."}, {"id": "ef993523-f7e9-4a85-8dfd-152976aa59d2", "type": "subtopic", "title": "Humanitarian reason", "children": [{"id": "f73edcd8-06ae-4396-a63b-1ae45ac0a61b", "type": "concept", "title": "Humanitarianism"}, {"id": "ab342124-3a27-4add-ae10-d0942eb4d853", "type": "concept", "title": "Emergency"}, {"id": "d2af7fd0-a3ec-447a-98d3-1fd159ff01b6", "type": "concept", "title": "Triage"}, {"id": "7a3cf412-b148-4bc0-8115-dedb2d58f3b9", "type": "concept", "title": "Witnessing"}, {"id": "3d63cce6-fc6a-46cd-af92-3c9d12dcb49b", "type": "concept", "title": "Neutrality"}, {"id": "e27d089d-099c-44e8-af7e-0f94db934a55", "type": "concept", "title": "Victim subject"}], "description": "Students analyze emergency aid, suffering, compassion, triage, and the politics of saving lives."}]}, {"id": "057ddf03-0027-4de2-b137-e5ad4fdadf3a", "type": "topic", "title": "The State, Bureaucracy, and Everyday Governance", "description": "Explores the state not only as an institution but as a set of documents, encounters, infrastructures, categories, and performances.", "children": [{"id": "d07aabd8-12ab-45c7-98e9-93e37286729b", "type": "subtopic", "title": "Anthropology of the state", "children": [{"id": "2f4acceb-dc3c-4c9a-b065-9ecf55841053", "type": "concept", "title": "State effect"}, {"id": "84f8c6f4-8aeb-4595-a6df-3759834aa925", "type": "concept", "title": "Legibility"}, {"id": "5567ac92-a802-4a97-ad44-dde44f1390e1", "type": "concept", "title": "Governmentality"}, {"id": 